{
  "packet_id": "H6-T01-1",
  "claim_id": "C054",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C054.component",
    "value": "The persistence rule is a provisional practical selection criterion.",
    "scope": "The rule requiring recurrence across booking days and the same leading delay stage in both investigation weeks.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P011 defines the provisional rule; P025 explicitly identifies its practical selection role and excludes statistical proof or causal identification."
    }
  },
  "signal_basis": {
    "component_id": "C054.signal_basis",
    "value": "Comparable turnaround observations show a candidate bottleneck recurring on multiple booking days in each investigation week, with the same stage contributing the greatest documented delay burden in both weeks. Sparse bookings or missing records capable of reversing the ranking prevent treating a bottleneck as established.",
    "scope": "The two-week investigation, using the recurrence rule for practical selection rather than statistical proof or causal identification.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply comparable recording, the exact recurrence and delay-ranking conditions, the sparse-data and missing-record restrictions, and the rule's limited evidential role."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C054.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim describes the rule's explicitly assigned practical role; no unresolved empirical relation is required to license that description."
    }
  },
  "rationale": "The mapping expressly adopts this rule as a provisional decision criterion. The claim accurately characterizes that limited role without asserting that meeting the rule proves persistence, identifies a cause, or guarantees a successful intervention.",
  "uncertainty": "The rule's empirical reliability is not established, but the frozen claim does not assert reliability.",
  "anomalies": []
}
